144	+public class MinimalImportScanner extends ImportScannerImpl implements ImportScanner {
145	+
146	+	private Set<String> namedElements = new HashSet<String>();
147	+
148	+	/**
149	+	 * Test if the reference should be imported by looking if there is a name conflict
150	+	 * @param ref
151	+	 * @return true if the ref should be imported.
152	+	 */
153	+	private boolean shouldTypeBeImported(CtTypeReference<?> ref) {
154	+		// we import the targetType by default to simplify and avoid conclict in inner classes
155	+		if (ref.equals(targetType)) {
156	+			return true;
157	+		}
158	+
159	+		try {
160	+			CtElement parent = ref.getParent();
161	+
162	+			if (parent instanceof CtNamedElement) {
163	+				namedElements.add(((CtNamedElement) parent).getSimpleName());
164	+			}
165	+
166	+			while (!(parent instanceof CtPackage)) {
167	+				if (parent instanceof CtFieldReference) {
168	+					CtFieldReference parentType = (CtFieldReference) parent;
169	+					Set<String> qualifiedNameTokens = new HashSet<>();
170	+
171	+					qualifiedNameTokens.add(parentType.getSimpleName());
172	+
173	+					CtTypeReference typeReference = parentType.getDeclaringType();
174	+
175	+					qualifiedNameTokens.add(typeReference.getSimpleName());
176	+
177	+					if (typeReference.getPackage() != null) {
178	+						CtPackage ctPackage = typeReference.getPackage().getDeclaration();
179	+
180	+						while (ctPackage != null) {
181	+							qualifiedNameTokens.add(ctPackage.getSimpleName());
182	+
183	+							CtElement packParent = ctPackage.getParent();
184	+							if (packParent.getParent() != null) {
185	+								ctPackage = (CtPackage) packParent;
186	+							} else {
187	+								ctPackage = null;
188	+							}
189	+						}
190	+
191	+						for (String token : qualifiedNameTokens) {
192	+							if (namedElements.contains(token)) {
193	+								return true;
194	+							}
195	+						}
196	+					}
197	+				}
198	+				parent = parent.getParent();
199	+			}
200	+		} catch (ParentNotInitializedException e) {
201	+			return false;
202	+		}
203	+
204	+		return false;
205	+	}
206	+
207	+	@Override
208	+	protected boolean addImport(CtTypeReference<?> ref) {
209	+		boolean shouldTypeBeImported = this.shouldTypeBeImported(ref);
210	+
211	+		if (shouldTypeBeImported) {
212	+			return super.addImport(ref);
213	+		} else {
214	+			return false;
215	+		}
216	+	}
217	+}
